import{_ as e,o as d,c as o,a3 as r}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Live Chat 1.5.0 / 1.5.1 — Send Resilience + Typing Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat 1.5.0 / 1.5.1 — Send Resilience + Typing Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/live-chat-1-5-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat 1.5.0 / 1.5.1 — Send Resilience + Typing Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/live-chat-1-5-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/live-chat-1-5-0-production-readiness.md","filePath":"deployment/live-chat-1-5-0-production-readiness.md","lastUpdated":1790429850000}'),i={name:"deployment/live-chat-1-5-0-production-readiness.md"};function n(a,t,s,c,l,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="live-chat-1-5-0-1-5-1-—-send-resilience-typing-production-readiness-audit" tabindex="-1">Live Chat 1.5.0 / 1.5.1 — Send Resilience + Typing Production Readiness Audit <a class="header-anchor" href="#live-chat-1-5-0-1-5-1-—-send-resilience-typing-production-readiness-audit" aria-label="Permalink to &quot;Live Chat 1.5.0 / 1.5.1 — Send Resilience + Typing Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-25</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — migrate catalog through <strong>1.5.1</strong>; deploy Backend (widget JS + soft-fail hardening) + Frontend; Reverb preferred for typing/desk live updates</td></tr><tr><td><strong>Scope</strong></td><td>Free Communication module <code>live-chat</code> <strong>1.4.2 → 1.5.0 → 1.5.1</strong> (send soft-fail; typing; embed Retry; desk <code>/</code> canned filter; open/close soft-fail; embed send lock + hydrate-before-retry; snippet <code>?v=</code> cache-bust; structured side-effect logs)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./live-chat">Live Chat deployment</a> · <a href="./live-chat-production-readiness">1.0.1 readiness</a> · <a href="/developer-guide/live-chat">Developer</a> · <a href="/user-guide/live-chat">User</a> · <a href="/user-guide/live-chat-overview">Overview</a> · <a href="/api/tenant-v1-live-chat">API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><p>Additive <strong>MINOR</strong> (<strong>1.5.0</strong>) plus <strong>PATCH</strong> remediations (<strong>1.5.1</strong>) on the existing Live Chat module. No new permissions, queues, scheduler entries, or env vars. Prior <a href="./live-chat-production-readiness">1.0.1 production readiness</a> remains the baseline security/CORS/session audit; this page covers <strong>1.5.0 / 1.5.1</strong>.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Production embeds (e.g. third-party marketing sites) and the agent desk could both fail message send with HTTP <strong>500</strong> when <code>ShouldBroadcastNow</code> / notify / automation threw after persist (commonly a down or misconfigured Reverb). <strong>1.5.0</strong> soft-fails those side effects after the message row commits, so visitors and agents can always send. Typing is fan-out via public + tenant <code>POST …/typing</code> → <code>LiveChatTyping</code> (private inbox/conversation + public visitor channel). The embed replaces browser <code>alert()</code> with an in-panel error + <strong>Retry</strong>. The desk filters canned replies when the composer starts with <code>/</code>.</p><p><strong>1.5.1</strong> closes remaining audit gaps: soft-fail <code>LiveChatConversationOpened</code> / <code>Closed</code> and webhook/automation <code>forward()</code>; structured <code>Log::warning</code> for side-effect failures; embed send lock + hydrate-before-retry (avoids duplicate posts when Retry follows a soft-failed persist); embed snippet <code>?v=</code> cache-bust aligned to catalog PATCH.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog migrate-only <strong>1.4.2 → 1.5.0</strong> (<code>2026_09_25_142200_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Catalog migrate-only <strong>1.5.0 → 1.5.1</strong> (<code>2026_09_25_200000_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>No schema / permission / env changes</td><td><strong>Pass</strong></td></tr><tr><td>Visitor + agent send soft-fail notify / broadcast / automation after persist</td><td><strong>Pass</strong></td></tr><tr><td>Conversation open / close lifecycle soft-fail</td><td><strong>Pass</strong></td></tr><tr><td>Conversation-updated + presence broadcasts soft-fail</td><td><strong>Pass</strong></td></tr><tr><td>Integration webhook/automation <code>forward()</code> soft-fail</td><td><strong>Pass</strong></td></tr><tr><td>Public <code>POST …/typing</code> (Bearer session) + tenant <code>POST …/typing</code> (<code>live-chat.reply</code>)</td><td><strong>Pass</strong></td></tr><tr><td><code>LiveChatTyping</code> on private + public visitor channels</td><td><strong>Pass</strong></td></tr><tr><td>Embed: in-panel error + Retry; send lock; hydrate-before-retry; visitor typing; agent-is-typing</td><td><strong>Pass</strong></td></tr><tr><td>Embed snippet includes <code>widgets/live-chat.js?v=1.5.1</code></td><td><strong>Pass</strong></td></tr><tr><td>Desk: typing API fan-out + <code>/</code> canned filter</td><td><strong>Pass</strong></td></tr><tr><td>Prior CORS / entitlement / PII / session TTL / IDOR gates (1.0.1+)</td><td><strong>Pass</strong> (unchanged)</td></tr><tr><td>Pest <code>LiveChatModuleTest</code> incl. broadcast-outage send, open/close soft-fail, typing, embed snippet</td><td><strong>Pass</strong> (28, verified 2026-09-25)</td></tr><tr><td>Playwright <code>test:e2e:live-chat</code> (10, shared demo session)</td><td><strong>Pass</strong> (verified 2026-09-25 on 1.5.0 baseline)</td></tr><tr><td>Docs hubs + roadmap <strong>1.5.1</strong> + this page</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI green and:</p><ol><li><code>php artisan migrate --force</code> (catalog through <strong>1.5.1</strong>)</li><li>Backend deploy that serves updated <code>public/widgets/live-chat.js</code></li><li>Frontend SPA deploy</li><li>Staging smoke below (third-party Origin embed + desk send); re-copy Settings embed snippet if sites still load unversioned script without CDN purge</li></ol><p>Reverb remaining down does <strong>not</strong> block send or conversation open/close; it only degrades typing indicators and live inbox updates (poll fallback remains).</p><hr><h2 id="incident-→-remediation-map" tabindex="-1">Incident → remediation map <a class="header-anchor" href="#incident-→-remediation-map" aria-label="Permalink to &quot;Incident → remediation map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom (pre-1.5.0)</th><th>Root cause</th><th>Fix</th></tr></thead><tbody><tr><td>Website widget <code>POST …/messages</code> → 500; <code>alert(&quot;Server Error&quot;)</code></td><td>Sync broadcast / notify / automation after persist</td><td>Soft-fail + <code>report()</code> / structured log; embed in-panel Retry</td></tr><tr><td>Agent desk send → toast / fail</td><td>Same <code>broadcastMessageSent</code> path</td><td>Soft-fail on agent send</td></tr><tr><td>Typing only agent↔agent (whisper)</td><td>Visitors not on private Echo channels</td><td>HTTP typing + <code>LiveChatTyping</code> on public visitor channel</td></tr><tr><td>Open/close could 500 on automation fan-out</td><td>Unwrapped <code>event(Opened/Closed)</code></td><td>Soft-fail in <strong>1.5.1</strong></td></tr><tr><td>Stale embed script after deploy</td><td>Long-lived CDN / browser cache</td><td>Snippet <code>?v=</code> + redeploy (<strong>1.5.1</strong> / O2)</td></tr></tbody></table><hr><h2 id="findings-1-5-0-audit-→-1-5-1-remediations" tabindex="-1">Findings (1.5.0 audit → 1.5.1 remediations) <a class="header-anchor" href="#findings-1-5-0-audit-→-1-5-1-remediations" aria-label="Permalink to &quot;Findings (1.5.0 audit → 1.5.1 remediations)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>LC15-01</td><td>Critical</td><td><strong>Fixed</strong></td><td>Reverb/<code>ShouldBroadcastNow</code> outage 500’d visitor + agent send</td><td>Soft-fail side effects after message persist</td></tr><tr><td>LC15-02</td><td>High</td><td><strong>Fixed</strong></td><td>Embed used <code>alert()</code> for API errors</td><td>In-panel banner + Retry</td></tr><tr><td>LC15-03</td><td>Medium</td><td><strong>Fixed</strong></td><td>No visitor↔agent typing surface</td><td>Public/tenant typing routes + <code>LiveChatTypingBroadcast</code></td></tr><tr><td>LC15-04</td><td>Medium</td><td><strong>Fixed</strong></td><td>Desk canned chips only (no <code>/</code> filter)</td><td>Composer <code>/</code> filters shortcuts/titles</td></tr><tr><td>LC15-05</td><td>Low</td><td><strong>Fixed</strong></td><td>E2E tinker preferred Herd PHP 8.4 on Windows</td><td><code>verify-tenant-email.ts</code> prefers <code>php85</code></td></tr><tr><td>LC15-06</td><td>Low</td><td><strong>Fixed (1.5.1)</strong></td><td>Soft-fail can leave message saved if client retries</td><td>Embed send lock + hydrate-before-retry skips re-POST when visitor body already painted</td></tr><tr><td>LC15-07</td><td>Medium</td><td><strong>Fixed (1.5.1)</strong></td><td>Conversation open/close automation could 500 the HTTP path</td><td>Soft-fail <code>LiveChatConversationOpened</code> / <code>Closed</code></td></tr><tr><td>LC15-08</td><td>Medium</td><td><strong>Fixed (1.5.1)</strong></td><td>Webhook/automation <code>forward()</code> unwrapped</td><td>try/catch + structured log in <code>IntegrationEventDispatcher</code></td></tr></tbody></table><h3 id="ops-not-code-blockers" tabindex="-1">Ops (not code blockers) <a class="header-anchor" href="#ops-not-code-blockers" aria-label="Permalink to &quot;Ops (not code blockers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Owner</th></tr></thead><tbody><tr><td>O1</td><td>Medium</td><td>Open</td><td>Keep Reverb daemon healthy for typing + live desk (send works without it)</td><td>Ops</td></tr><tr><td>O2</td><td>Medium</td><td><strong>Mitigated (1.5.1)</strong></td><td>Redeploy API static <code>widgets/live-chat.js</code> (CDN purge if fronted); new snippets use <code>?v=1.5.1</code></td><td>Ops / Eng</td></tr><tr><td>O3</td><td>Low</td><td>Open</td><td>Customer site embeds: refresh snippet from Settings after <strong>1.5.1</strong> (or purge CDN for unversioned URLs)</td><td>Customer / CS</td></tr><tr><td>O4</td><td>Low</td><td><strong>Mitigated (1.5.1)</strong></td><td>Monitor <code>live-chat.side-effect-failed</code> / <code>integrations.forward-failed</code> + <code>report()</code> volume</td><td>Ops / Eng</td></tr></tbody></table><h3 id="explicitly-deferred-unchanged" tabindex="-1">Explicitly deferred (unchanged) <a class="header-anchor" href="#explicitly-deferred-unchanged" aria-label="Permalink to &quot;Explicitly deferred (unchanged)&quot;">​</a></h3><ul><li>Captcha / Turnstile beyond throttle + session TTL</li><li>Bots / FAQ flows; invoice/record share in chat</li><li>Multi-widget / multi-domain brands</li><li>Mobile agent shell</li></ul><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>herd php vendor/bin/pest tests/Feature/Tenant/LiveChat/LiveChatModuleTest.php --compact</code></td><td><strong>28 passed</strong> (verified 2026-09-25)</td><td>Soft-fail send; open/close soft-fail; typing; embed <code>?v=</code> snippet</td></tr><tr><td><code>npm run test:e2e:live-chat</code> (shared demo session, <code>E2E_SKIP_WEBSERVER=1</code>)</td><td><strong>10 passed</strong></td><td>Gate → entitle → validation → visitor send → reply → note hidden from public → typing → claim/close → lead → search</td></tr></tbody></table><p>Do <strong>not</strong> claim CI green until companion PRs’ Quality Gates pass on the merge branch.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Companion <strong>CI</strong> green (Backend / Frontend / Docs)</li><li><strong>Backend</strong> — <code>php artisan migrate --force</code> through <code>2026_09_25_200000_bump_live_chat_module_version_to_1_5_1</code>; confirm <code>public/widgets/live-chat.js</code> is the 1.5.1 artifact; <code>php artisan reverb:restart</code> if Reverb is used</li><li><strong>Frontend</strong> — SPA with typing API + <code>/</code> canned filter</li><li><strong>Docs</strong> — this page live</li><li>Staging smoke below before pointing production marketing embeds at the new API build</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrate through <code>2026_09_25_200000_…</code>; catalog <code>live-chat</code> = <strong>1.5.1</strong></td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>API serves updated <code>GET {APP_URL}/widgets/live-chat.js</code> (and Settings snippet uses <code>?v=1.5.1</code>)</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Reverb daemon up <strong>or</strong> accepted degraded typing (send still works)</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Scheduler still runs <code>live-chat:purge-visitors --days=90</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Pest Live Chat suite green on CI</td><td>Eng</td><td>☐</td></tr><tr><td>6</td><td>Playwright <code>test:e2e:live-chat</code> green on CI</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>Staging third-party Origin: visitor send + agent reply without 500</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace: workspace with Live Chat <strong>1.5.1</strong> entitled; widget Active</li><li>From a <strong>foreign Origin</strong> (or Diligent Creators staging): open widget → send message → expect <strong>201</strong>, no <code>&quot;Server Error&quot;</code> alert; Retry banner only on real failures; double-click send does not duplicate</li><li>Stop Reverb briefly (staging only) → send still succeeds; typing may stall; restore Reverb</li><li>Agent desk: reply appears; empty compose disabled; internal <strong>Note</strong> visible in desk, absent from public poll</li><li>Type in visitor composer → agent sees typing; type in desk → visitor sees “is typing…” when realtime connected</li><li>Desk composer <code>/</code> → canned filter chips; insert body</li><li>Claim / close / reopen; search by visitor name</li><li>Optional: require prechat → session without name/email → <strong>422</strong></li><li>Confirm Settings embed snippet contains <code>live-chat.js?v=1.5.1</code></li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive catalog migrations</td></tr><tr><td>Module</td><td>Marketplace cancel / deactivate widgets (existing path)</td></tr><tr><td>Schema</td><td>No schema rollback — catalog bump only</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Public + tenant <code>POST …/messages</code> <strong>5xx</strong> rate (should drop vs pre-1.5.0)</li><li>Structured logs: <code>live-chat.side-effect-failed</code>, <code>integrations.forward-failed</code></li><li><code>report()</code> / Nightwatch events mentioning <code>LiveChatMessageSentBroadcast</code> / Reverb connection errors</li><li>Throttle denials on <code>live-chat-widget</code> / <code>live-chat-widget-session</code></li><li>Typing endpoint 401/403/404 vs volume</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> <strong>Go</strong> — ship companions after CI green; migrate to catalog <strong>1.5.1</strong> and redeploy API widget script before relying on production embeds (diligentcreators.com and peers).</p>',45)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
